    "approval-token.schema.json": "{\n  \"$schema\": \"https://json-schema.org/draft/2020-12/schema\",\n  \"$id\": \"https://use-cases.dev/schemas/v1/approval-token.schema.json\",\n  \"title\": \"ucase-approval-token-v1\",\n  \"description\": \"F3 trusted human approval. A REQUEST is minted by the plugin (single-use nonce + run binding + expiry) and carries a PLUGIN-minted jti the caller never chooses. A TOKEN is the request signed OUT-OF-BAND by a real human with either an ed25519 key held outside the in-session agent's scope or a WebAuthn/passkey authenticator assertion. The plugin then re-checks every bound field against the live run, the nonce (single-use), the expiry, the signed/proven assurance tier, and the keyring-bound max_assurance_tier before appending an approval. Trust is COMPUTED from the signature/assertion; it is never a caller-asserted boolean.\",\n  \"type\": \"object\",\n  \"$defs\": {\n    \"binding\": {\n      \"type\": \"object\",\n      \"additionalProperties\": false,\n      \"description\": \"The run facts the token is pinned to; each is re-checked against the LIVE run at verify time.\",\n      \"properties\": {\n        \"run_id\": { \"type\": \"string\", \"minLength\": 1 },\n        \"finish_event_id\": { \"type\": \"string\", \"minLength\": 1 },\n        \"plan_content_hash\": { \"type\": \"string\" },\n        \"ledger_head_hash\": { \"type\": \"string\" },\n        \"evidence_digest\": { \"type\": \"string\" },\n        \"git_commit\": { \"type\": \"string\" },\n        \"ci_freshness_digest\": { \"type\": \"string\" }\n      },\n      \"required\": [\n        \"run_id\",\n        \"finish_event_id\",\n        \"plan_content_hash\",\n        \"ledger_head_hash\",\n        \"evidence_digest\",\n        \"git_commit\",\n        \"ci_freshness_digest\"\n      ]\n    },\n    \"ed25519_signature\": {\n      \"type\": \"object\",\n      \"additionalProperties\": false,\n      \"description\": \"ed25519 signature block (identical shape to a proof event's signature).\",\n      \"properties\": {\n        \"alg\": { \"const\": \"ed25519\" },\n        \"key_id\": { \"type\": \"string\", \"minLength\": 1 },\n        \"value\": { \"type\": \"string\", \"minLength\": 1, \"description\": \"base64-encoded ed25519 signature over canonical_json(token minus signature).\" }\n      },\n      \"required\": [\"alg\", \"key_id\", \"value\"]\n    },\n    \"webauthn_signature\": {\n      \"type\": \"object\",\n      \"additionalProperties\": false,\n      \"description\": \"WebAuthn assertion block. The verifier checks clientDataJSON.type, challenge, UP+UV flags, and the signature over authenticatorData || SHA-256(clientDataJSON) against a pinned credential.\",\n      \"properties\": {\n        \"alg\": { \"const\": \"webauthn\" },\n        \"credential_id\": {\n          \"type\": \"string\",\n          \"minLength\": 1,\n          \"pattern\": \"^[A-Za-z0-9_-]+$\"\n        },\n        \"authenticator_data\": {\n          \"type\": \"string\",\n          \"minLength\": 1,\n          \"pattern\": \"^[A-Za-z0-9_-]+$\",\n          \"description\": \"base64url authenticatorData bytes.\"\n        },\n        \"client_data_json\": {\n          \"type\": \"string\",\n          \"minLength\": 1,\n          \"pattern\": \"^[A-Za-z0-9_-]+$\",\n          \"description\": \"base64url clientDataJSON bytes.\"\n        },\n        \"signature\": {\n          \"type\": \"string\",\n          \"minLength\": 1,\n          \"pattern\": \"^[A-Za-z0-9_-]+$\",\n          \"description\": \"base64url signature over authenticatorData || SHA-256(clientDataJSON).\"\n        }\n      },\n      \"required\": [\"alg\", \"credential_id\", \"authenticator_data\", \"client_data_json\", \"signature\"]\n    },\n    \"signature\": {\n      \"oneOf\": [\n        { \"$ref\": \"#/$defs/ed25519_signature\" },\n        { \"$ref\": \"#/$defs/webauthn_signature\" }\n      ]\n    },\n    \"assurance_method\": {\n      \"enum\": [\"automation\", \"same_channel\", \"os_presence\", \"webauthn\"],\n      \"description\": \"The signed method by which the human approval was gated.\"\n    },\n    \"request\": {\n      \"type\": \"object\",\n      \"additionalProperties\": false,\n      \"description\": \"The plugin-minted, unsigned approval request handed to a human to sign.\",\n      \"properties\": {\n        \"approval_request_schema\": { \"const\": \"ucase-approval-request-v1\" },\n        \"binding\": { \"$ref\": \"#/$defs/binding\" },\n        \"jti\": { \"type\": \"string\", \"minLength\": 1, \"description\": \"Single-use nonce, minted by the PLUGIN (never by the caller).\" },\n        \"iat\": { \"$ref\": \"common.schema.json#/$defs/timestamp\" },\n        \"exp\": { \"$ref\": \"common.schema.json#/$defs/timestamp\" }\n      },\n      \"required\": [\"approval_request_schema\", \"binding\", \"jti\", \"iat\", \"exp\"]\n    },\n    \"token\": {\n      \"type\": \"object\",\n      \"additionalProperties\": false,\n      \"description\": \"A request signed out-of-band by a human. The signature covers everything except itself.\",\n      \"properties\": {\n        \"approval_token_schema\": { \"const\": \"ucase-approval-token-v1\" },\n        \"binding\": { \"$ref\": \"#/$defs/binding\" },\n        \"jti\": { \"type\": \"string\", \"minLength\": 1 },\n        \"iat\": { \"$ref\": \"common.schema.json#/$defs/timestamp\" },\n        \"exp\": { \"$ref\": \"common.schema.json#/$defs/timestamp\" },\n        \"created_at\": { \"$ref\": \"common.schema.json#/$defs/timestamp\" },\n        \"decision\": { \"enum\": [\"approved\", \"approved_with_known_gaps\", \"rejected\"] },\n        \"assurance_method\": { \"$ref\": \"#/$defs/assurance_method\" },\n        \"assurance_tier\": { \"$ref\": \"common.schema.json#/$defs/approval_assurance_tier\" },\n        \"signature\": { \"$ref\": \"#/$defs/signature\" }\n      },\n      \"dependentRequired\": {\n        \"assurance_method\": [\"assurance_tier\"],\n        \"assurance_tier\": [\"assurance_method\"]\n      },\n      \"required\": [\n        \"approval_token_schema\",\n        \"binding\",\n        \"jti\",\n        \"iat\",\n        \"exp\",\n        \"created_at\",\n        \"decision\",\n        \"signature\"\n      ]\n    }\n  },\n  \"oneOf\": [\n    { \"$ref\": \"#/$defs/request\" },\n    { \"$ref\": \"#/$defs/token\" }\n  ],\n  \"examples\": [\n    {\n      \"approval_request_schema\": \"ucase-approval-request-v1\",\n      \"binding\": {\n        \"run_id\": \"run.alpha\",\n        \"finish_event_id\": \"evt.run.alpha.7\",\n        \"plan_content_hash\": \"sha256:plan\",\n        \"ledger_head_hash\": \"sha256:head\",\n        \"evidence_digest\": \"sha256:evidence\",\n        \"git_commit\": \"0123456789abcdef0123456789abcdef01234567\",\n        \"ci_freshness_digest\": \"sha256:ci\"\n      },\n      \"jti\": \"approval.9d8f54b2-7a0d-4bc2-ad35-9035dcb623c5\",\n      \"iat\": \"2026-06-28T12:05:00.000Z\",\n      \"exp\": \"2026-06-28T12:20:00.000Z\"\n    },\n    {\n      \"approval_token_schema\": \"ucase-approval-token-v1\",\n      \"binding\": {\n        \"run_id\": \"run.alpha\",\n        \"finish_event_id\": \"evt.run.alpha.7\",\n        \"plan_content_hash\": \"sha256:plan\",\n        \"ledger_head_hash\": \"sha256:head\",\n        \"evidence_digest\": \"sha256:evidence\",\n        \"git_commit\": \"0123456789abcdef0123456789abcdef01234567\",\n        \"ci_freshness_digest\": \"sha256:ci\"\n      },\n      \"jti\": \"approval.9d8f54b2-7a0d-4bc2-ad35-9035dcb623c5\",\n      \"iat\": \"2026-06-28T12:05:00.000Z\",\n      \"exp\": \"2026-06-28T12:20:00.000Z\",\n      \"created_at\": \"2026-06-28T12:05:00.000Z\",\n      \"decision\": \"approved\",\n      \"assurance_method\": \"os_presence\",\n      \"assurance_tier\": \"trusted_host_user_presence\",\n      \"signature\": {\n        \"alg\": \"ed25519\",\n        \"key_id\": \"human-key-1\",\n        \"value\": \"dmFsaWQtYmFzZTY0LXNpZ25hdHVyZS1wbGFjZWhvbGRlcg==\"\n      }\n    },\n    {\n      \"approval_token_schema\": \"ucase-approval-token-v1\",\n      \"binding\": {\n        \"run_id\": \"run.alpha\",\n        \"finish_event_id\": \"evt.run.alpha.7\",\n        \"plan_content_hash\": \"sha256:plan\",\n        \"ledger_head_hash\": \"sha256:head\",\n        \"evidence_digest\": \"sha256:evidence\",\n        \"git_commit\": \"0123456789abcdef0123456789abcdef01234567\",\n        \"ci_freshness_digest\": \"sha256:ci\"\n      },\n      \"jti\": \"approval.9d8f54b2-7a0d-4bc2-ad35-9035dcb623c5\",\n      \"iat\": \"2026-06-28T12:05:00.000Z\",\n      \"exp\": \"2026-06-28T12:20:00.000Z\",\n      \"created_at\": \"2026-06-28T12:05:00.000Z\",\n      \"decision\": \"approved\",\n      \"assurance_method\": \"webauthn\",\n      \"assurance_tier\": \"webauthn_hardware\",\n      \"signature\": {\n        \"alg\": \"webauthn\",\n        \"credential_id\": \"Y3JlZGVudGlhbC0x\",\n        \"authenticator_data\": \"dmFsaWQtYXV0aGVudGljYXRvci1kYXRh\",\n        \"client_data_json\": \"dmFsaWQtY2xpZW50LWRhdGE\",\n        \"signature\": \"dmFsaWQtc2lnbmF0dXJl\"\n      }\n    }\n  ]\n}\n",
    "authority.schema.json": "{\n  \"$schema\": \"https://json-schema.org/draft/2020-12/schema\",\n  \"$id\": \"https://use-cases.dev/schemas/v1/authority.schema.json\",\n  \"title\": \"ucase-authority-v1\",\n  \"description\": \"CI-neutral provenance authority for a proof event. The trust model is CI-NEUTRAL: GitHub Actions is only the reference provider. This record captures WHO/WHERE produced a proof in a provider-agnostic shape (type + provider + best-effort repository/ref/commit/run_id/actor/event), auto-detected from CI env vars (see markers/ciAuthority.ts detectCiAuthority) or supplied explicitly via `prove --authority-file`. It is OPTIONAL on a proof event and ADDITIVE: it does not affect freshness (FRESH matches row/binding/context hashes, not provenance). When present it is built INTO the event before signing, so the signature covers it. `protected_ref` is a tri-state: true/false when the provider exposes an explicit protected-branch signal, and null when unknown.\",\n  \"type\": \"object\",\n  \"additionalProperties\": false,\n  \"properties\": {\n    \"type\": {\n      \"enum\": [\"ci\", \"local\"],\n      \"description\": \"\\\"ci\\\" when produced inside a recognised CI provider; \\\"local\\\" otherwise.\"\n    },\n    \"provider\": {\n      \"enum\": [\"github-actions\", \"gitlab-ci\", \"circleci\", \"generic\"],\n      \"description\": \"The CI provider. \\\"generic\\\" is the fallback for local runs or an unrecognised provider.\"\n    },\n    \"repository\": {\n      \"type\": \"string\",\n      \"minLength\": 1,\n      \"description\": \"Provider-shaped repository identifier (e.g. owner/repo).\"\n    },\n    \"ref\": {\n      \"type\": \"string\",\n      \"minLength\": 1,\n      \"description\": \"The git ref / branch the run executed against.\"\n    },\n    \"commit\": {\n      \"type\": \"string\",\n      \"minLength\": 1,\n      \"description\": \"The commit SHA the run executed against.\"\n    },\n    \"run_id\": {\n      \"type\": \"string\",\n      \"minLength\": 1,\n      \"description\": \"The provider's run / pipeline / build identifier.\"\n    },\n    \"actor\": {\n      \"type\": \"string\",\n      \"minLength\": 1,\n      \"description\": \"The user/login that triggered the run, when the provider exposes it.\"\n    },\n    \"protected_ref\": {\n      \"type\": [\"boolean\", \"null\"],\n      \"description\": \"Whether the ref is a protected branch. true/false when the provider exposes an explicit signal; null when unknown.\"\n    },\n    \"event\": {\n      \"type\": \"string\",\n      \"minLength\": 1,\n      \"description\": \"The provider's triggering event name (e.g. push, pull_request, merge_request).\"\n    }\n  },\n  \"required\": [\"type\", \"provider\"],\n  \"examples\": [\n    {\n      \"type\": \"ci\",\n      \"provider\": \"github-actions\",\n      \"repository\": \"use-cases/use-cases\",\n      \"ref\": \"refs/heads/main\",\n      \"commit\": \"0123456789abcdef0123456789abcdef01234567\",\n      \"run_id\": \"1234567890\",\n      \"actor\": \"octocat\",\n      \"protected_ref\": null,\n      \"event\": \"push\"\n    },\n    {\n      \"type\": \"local\",\n      \"provider\": \"generic\"\n    }\n  ]\n}\n",
